import { useQuery, type UseQueryOptions } from "@tanstack/react-query";
import { getSpace } from "../handlers/getSpace";
import type { ApiError } from "../runtime/client";
import type { SpacePartition } from "../types/SpacePartition";

type Data = Awaited<ReturnType<typeof getSpace>>;

export function useGetSpace(
  spaceId: SpacePartition,
  options?: Omit<UseQueryOptions<Data, ApiError>, "queryKey" | "queryFn">,
) {
  return useQuery<Data, ApiError>({
    queryKey: ["getSpace", spaceId],
    queryFn: () => getSpace(spaceId),
    ...options,
  });
}
